%% 1. EMPIRICAL SHANNON ENTROPY ON REAL COMPILED BYTECODE CORPUS
disp("\n[1] EMPIRICAL BYTECODE ENTROPY ON ACTUAL COMPILED ARTIFACTS");
disp("-------------------------------------------------------------------------");

bytecode_path = "binaries/protected_demo/protected.vanguard";
if exist(bytecode_path, "file") == 2
    fid = fopen(bytecode_path, "rb");
    raw_bytes = fread(fid, Inf, "uint8");
    fclose(fid);
    
    N_bytes = length(raw_bytes);
    [byte_counts, ~] = hist(double(raw_bytes), 0:255);
    p = byte_counts / N_bytes;
    p_nz = p(p > 0);
    H_actual = -sum(p_nz .* log2(p_nz));
    
    % Kullback-Leibler Divergence from Uniform Distribution U(0, 255)
    p_uniform = 1 / 256;
    D_kl = sum(p_nz .* log2(p_nz / p_uniform));
    
    fprintf("  Target Artifact:               %s\n", bytecode_path);
    fprintf("  Artifact Size:                 %d bytes (%d 64-bit words)\n", N_bytes, N_bytes / 8);
    fprintf("  Empirical Shannon Entropy:     %6.4f / 8.0000 bits/byte\n", H_actual);
    fprintf("  KL-Divergence from Uniform:    %6.4e (lower is closer to ideal PRF)\n", D_kl);
    fprintf("  Unique Bytes Observed:         %d / 256 byte values in corpus\n", length(p_nz));
else
    fprintf("  [!] Bytecode artifact '%s' not found.\n", bytecode_path);
    fprintf("      Run './random_visa protect -i examples/demo_hash.s' first.\n");
end

%% 2. EMPIRICAL Z3 SMT SOLVER VERIFICATION BENCHMARKS (QF_BV THEORY)
disp("\n[2] EMPIRICAL SMT-LIB2 / Z3 5.0.0 MBA EQUIVALENCE PROOF BENCHMARKS");
