%% 3. STATISTICAL MONTE CARLO AVALANCHE TEST (POLYNOMIAL ROLLING CHECKSUM)
disp("\n[3] MONTE CARLO AVALANCHE EVALUATION (NON-CRYPTOGRAPHIC ROLLING CHECKSUM)");
disp("-------------------------------------------------------------------------");
% NOTE: This is a fast polynomial rolling checksum designed for runtime
% tripwire detection against naive patches/breakpoints (0x90, 0xCC).
% It is NOT a cryptographic HMAC and is not secure against targeted forgery.

N_trials = 5000;
bit_flips = zeros(N_trials, 1);
FNV_PRIME = uint64(1099511628211);
seed = uint64(975943864);

% Synthetic 64-word bytecode vector to evaluate dispersion
sample_bc = uint64(randi([0, 2^31-1], 1, 64));

function h = compute_checksum(vec, seed_val)
    h = bitxor(uint32(2166136261), uint32(seed_val));
    for idx = 1:length(vec)
        h = bitxor(h, uint32(vec(idx)));
        h = mod(double(h) * 16777619 + idx, 4294967296);
    end
    h = uint32(h);
end

h_baseline = compute_checksum(sample_bc, seed);

for trial = 1:N_trials
    mutated = sample_bc;
    target_word = randi([1, length(sample_bc)]);
    target_bit = randi([0, 31]);
    mutated(target_word) = bitxor(uint32(mutated(target_word)), uint32(2^target_bit));
    
    h_mutated = compute_checksum(mutated, seed);
    diff_bits = bitxor(h_baseline, h_mutated);
    bit_flips(trial) = sum(bitget(diff_bits, 1:32));
end


mean_flips = mean(bit_flips);
std_flips = std(bit_flips);
avalanche_pct = (mean_flips / 32) * 100;
ci95_low = (mean_flips - 1.96 * (std_flips / sqrt(N_trials))) / 32 * 100;
ci95_high = (mean_flips + 1.96 * (std_flips / sqrt(N_trials))) / 32 * 100;
zero_detect_count = sum(bit_flips == 0);

fprintf("  Trials Run:                    %d random 1-bit mutations\n", N_trials);
fprintf("  Mean Bit Inversion (Avalanche): %5.2f%% (%.2f / 32 bits, target: 50.00%%)\n", ...
        avalanche_pct, mean_flips);
fprintf("  Standard Deviation (σ):        %.2f bits\n", std_flips);
fprintf("  95%% Confidence Interval:       [%5.2f%%, %5.2f%%]\n", ci95_low, ci95_high);
fprintf("  Undetected 1-Bit Tampering:    %d / %d trials (Empirical false-negative rate: %4.2e)\n", ...
        zero_detect_count, N_trials, zero_detect_count / N_trials);
fprintf("  [!] Security Note:             Intended for tamper detection, not cryptographic resistance.\n");

%% 4. FORMAL BIJECTION VERIFICATION: AFFINE STACK PERMUTATION
disp("\n[4] RING ISOMORPHISM & BIJECTION PROOF (AFFINE STACK PERMUTATION)");
disp("-------------------------------------------------------------------------");
M = 256; % Ring size Z_256
a = 37;  % Multiplier
b = 13;  % Additive displacement

sp = 0:(M-1);
f_sp = mod(sp .* a + b, M);

is_bijective = (length(unique(f_sp)) == M);
coprimality = gcd(a, M);

% Calculate cycle length starting from sp = 0
cur = 0;
cycle_len = 0;
visited = false(1, M);
while ~visited(cur + 1)
    visited(cur + 1) = true;
    cur = mod(cur * a + b, M);
    cycle_len = cycle_len + 1;
end

fprintf("  Transformation:                f(x) = (%d * x + %d) mod %d on Z_%d\n", a, b, M, M);
fprintf("  Coprimality Invariant gcd(a, M): %d (gcd == 1 proves Ring Automorphism)\n", coprimality);
fprintf("  Full Bijection Verification:   %s (Zero collisions across entire domain [0, 255])\n", ...
        mat2str(is_bijective));
fprintf("  Maximal Cycle Length:          %d / %d elements\n", cycle_len, M);

